# frozen_string_literal: true

RSpec.describe 'RuboCop::CLI --prune-todo', :isolated_environment do # rubocop:disable RSpec/DescribeClass
  subject(:cli) { RuboCop::CLI.new }

  include_context 'cli spec behavior'

  def create_todo_file(content)
    create_file('.rubocop_todo.yml', <<~YAML)
      # This configuration was generated by
      # `rubocop --auto-gen-config`
      # using RuboCop version 1.88.2.
      # The point is for the user to remove these configuration records
      # one by one as the offenses are removed from the code base.

      #{content.chomp}
    YAML
    create_file('.rubocop.yml', <<~YAML)
      inherit_from: .rubocop_todo.yml
    YAML
  end

  def useless_assignment_source
    ['def f', '  a = 1', '  2', 'end']
  end

  def clean_source
    ['def f', '  2', 'end']
  end

  it 'fails helpfully when there is no TODO file' do
    expect(cli.run(%w[--prune-todo])).to eq(2)
    expect($stderr.string).to include('No .rubocop_todo.yml found')
  end

  it 'cannot be combined with --auto-gen-config' do
    expect(cli.run(%w[--prune-todo --auto-gen-config])).to eq(2)
    expect($stderr.string).to include('--prune-todo cannot be combined with --auto-gen-config.')
  end

  it 'cannot be combined with --regenerate-todo' do
    expect(cli.run(%w[--prune-todo --regenerate-todo])).to eq(2)
    expect($stderr.string).to include('--prune-todo cannot be combined with --regenerate-todo.')
  end

  it 'cannot be combined with --autocorrect' do
    expect(cli.run(%w[--prune-todo -a])).to eq(2)
    expect($stderr.string).to include('--prune-todo cannot be combined with --autocorrect.')
  end

  it 'cannot be combined with path arguments' do
    create_todo_file(<<~YAML)
      Lint/UselessAssignment:
        Exclude:
          - 'example.rb'
    YAML
    expect(cli.run(%w[--prune-todo example.rb])).to eq(2)
    expect($stderr.string).to include('--prune-todo cannot be combined with path arguments.')
  end

  it 'does nothing when the TODO file has no Exclude entries' do
    create_todo_file(<<~YAML)
      # Offense count: 2
      Metrics/MethodLength:
        Max: 42
    YAML
    before = File.read('.rubocop_todo.yml')
    expect(cli.run(%w[--prune-todo])).to eq(0)
    expect($stdout.string).to include('Nothing to prune in .rubocop_todo.yml.')
    expect(File.read('.rubocop_todo.yml')).to eq(before)
  end

  it 'leaves the TODO file unchanged when all excluded files still offend' do
    create_file('example.rb', useless_assignment_source)
    create_todo_file(<<~YAML)
      # Offense count: 1
      # This cop supports safe autocorrection (--autocorrect).
      Lint/UselessAssignment:
        Exclude:
          - 'example.rb'
    YAML
    before = File.read('.rubocop_todo.yml')
    expect(cli.run(%w[--prune-todo])).to eq(0)
    expect($stdout.string).to include('Removed 0 exclusion(s) and 0 cop entry(ies)')
    expect(File.read('.rubocop_todo.yml')).to eq(before)
  end

  it 'removes fixed files from Exclude lists and updates the offense count' do
    create_file('fixed.rb', clean_source)
    create_file('still_bad.rb', ['def g', '  a = 1', '  b = 2', '  3', 'end'])
    create_todo_file(<<~YAML)
      # Offense count: 3
      # This cop supports safe autocorrection (--autocorrect).
      Lint/UselessAssignment:
        Exclude:
          - 'fixed.rb'
          - 'still_bad.rb'
    YAML
    expect(cli.run(%w[--prune-todo])).to eq(0)
    expect(File.read('.rubocop_todo.yml')).to include(<<~YAML)
      # Offense count: 2
      # This cop supports safe autocorrection (--autocorrect).
      Lint/UselessAssignment:
        Exclude:
          - 'still_bad.rb'
    YAML
    expect(File.read('.rubocop_todo.yml')).not_to include('fixed.rb')
  end

  it 'removes whole entries when all their files are fixed or deleted' do
    create_file('fixed.rb', clean_source)
    create_todo_file(<<~YAML)
      # Offense count: 2
      Lint/UselessAssignment:
        Exclude:
          - 'deleted.rb'
          - 'fixed.rb'

      # Offense count: 1
      Security/Eval:
        Exclude:
          - 'fixed.rb'
    YAML
    create_file('fixed.rb', ['def f(x)', '  eval(x)', 'end'])
    expect(cli.run(%w[--prune-todo])).to eq(0)
    expect($stdout.string).to include('Removed 2 exclusion(s) and 1 cop entry(ies)')
    todo = File.read('.rubocop_todo.yml')
    expect(todo).not_to include('Lint/UselessAssignment')
    expect(todo).to include("Security/Eval:\n  Exclude:\n    - 'fixed.rb'")
    # The TODO file inheritance is intact after pruning.
    expect(YAML.safe_load(todo)).to be_a(Hash)
  end

  it 'keeps entries for files that can no longer be parsed' do
    create_file('broken.rb', ['def f('])
    create_todo_file(<<~YAML)
      # Offense count: 1
      Lint/UselessAssignment:
        Exclude:
          - 'broken.rb'
    YAML
    before = File.read('.rubocop_todo.yml')
    expect(cli.run(%w[--prune-todo])).to eq(0)
    expect(File.read('.rubocop_todo.yml')).to eq(before)
  end

  it 'keeps entries of cops that are not known to the registry' do
    create_file('example.rb', clean_source)
    create_todo_file(<<~YAML)
      # Offense count: 1
      Unknown/VeryCustomCop:
        Exclude:
          - 'example.rb'
    YAML
    # Not inheriting the TODO file, since an unknown cop in the inherited
    # configuration is itself an error.
    create_file('.rubocop.yml', [''])
    before = File.read('.rubocop_todo.yml')
    expect(cli.run(%w[--prune-todo])).to eq(0)
    expect($stderr.string).to include('Keeping entry for unknown cop Unknown/VeryCustomCop.')
    expect(File.read('.rubocop_todo.yml')).to eq(before)
  end

  it 'only runs the listed cops on the files listed for them' do
    create_file('a.rb', useless_assignment_source)
    create_file('b.rb', ['def g(x)', '  eval(x)', 'end'])
    create_todo_file(<<~YAML)
      # Offense count: 1
      Lint/UselessAssignment:
        Exclude:
          - 'a.rb'

      # Offense count: 1
      Security/Eval:
        Exclude:
          - 'a.rb'
          - 'b.rb'
    YAML
    expect(cli.run(%w[--prune-todo])).to eq(0)
    todo = File.read('.rubocop_todo.yml')
    # a.rb still has the useless assignment, but no eval; b.rb still has eval.
    expect(todo).to include("Lint/UselessAssignment:\n  Exclude:\n    - 'a.rb'")
    expect(todo).to include("Security/Eval:\n  Exclude:\n    - 'b.rb'")
    expect(todo).not_to include("Security/Eval:\n  Exclude:\n    - 'a.rb'")
  end

  it 'treats files excluded by the configuration as not offending' do
    create_file('ignored/example.rb', useless_assignment_source)
    create_todo_file(<<~YAML)
      # Offense count: 1
      Lint/UselessAssignment:
        Exclude:
          - 'ignored/example.rb'
    YAML
    create_file('.rubocop.yml', <<~YAML)
      inherit_from: .rubocop_todo.yml

      AllCops:
        Exclude:
          - 'ignored/**/*'
    YAML
    expect(cli.run(%w[--prune-todo])).to eq(0)
    expect(File.read('.rubocop_todo.yml')).not_to include('Lint/UselessAssignment')
  end

  it 'can be narrowed with --only' do
    create_file('fixed.rb', clean_source)
    create_todo_file(<<~YAML)
      # Offense count: 1
      Lint/UselessAssignment:
        Exclude:
          - 'fixed.rb'

      # Offense count: 1
      Security/Eval:
        Exclude:
          - 'fixed.rb'
    YAML
    expect(cli.run(%w[--prune-todo --only Security/Eval])).to eq(0)
    todo = File.read('.rubocop_todo.yml')
    expect(todo).to include("Lint/UselessAssignment:\n  Exclude:\n    - 'fixed.rb'")
    expect(todo).not_to include('Security/Eval')
  end

  it 'produces the same result on a second, cached run' do
    create_file('fixed.rb', clean_source)
    create_file('still_bad.rb', useless_assignment_source)
    create_todo_file(<<~YAML)
      # Offense count: 2
      Lint/UselessAssignment:
        Exclude:
          - 'fixed.rb'
          - 'still_bad.rb'
    YAML
    expect(cli.run(%w[--prune-todo])).to eq(0)
    first = File.read('.rubocop_todo.yml')

    new_cli = RuboCop::CLI.new
    expect(new_cli.run(%w[--prune-todo])).to eq(0)
    expect(File.read('.rubocop_todo.yml')).to eq(first)
    expect(first).to include("Lint/UselessAssignment:\n  Exclude:\n    - 'still_bad.rb'")
  end
end
